{
    "corrected": "Rahul and I have two years of experience in sales.","mistakes": [
      {
        "wrong": "Myself Rahul and I",
        "right": "Rahul and I",
        "type": "grammar","explanation_hindi": "कर्ता (subject) के रूप में 'myself' का प्रयोग नहीं होता है।"
      },
      {
        "wrong": "am having",
        "right": "have",
        "type": "style","explanation_hindi": "अनुभव बताने के लिए 'have' का प्रयोग अधिक पेशेवर है।"
      }
    ]
  }

{
    "corrected": "I have been working in this company since 2019.","mistakes": [
      {
        "wrong": "am working",
        "right": "have been working","type": "grammar","explanation_hindi": "जब कोई काम अतीत में शुरू हुआ और अभी भी चल रहा है, तो Present Perfect Continuous का उपयोग करें।"
      }
    ]
  }

{
        "corrected": "Please revert to me today.","mistakes": [
            {
                "wrong": "revert back",
                "right": "revert",
                "type": "style","explanation_hindi": "revert mein 'back' ki zarurat nahi hai."
            },
            {
                "wrong": "today itself",
                "right": "today",
                "type": "style","explanation_hindi": "today itself ki jagah 'today' bolna zyada professional hai."
            }
        ]
    }

{
    "corrected": "We discussed the budget, and he said it was fine.","mistakes": [
      {
        "wrong": "discussed about",
        "right": "discussed","type": "grammar","explanation_hindi": "discuss के साथ about का प्रयोग नहीं होता है।"
      },
      {
        "wrong": "he told that it is fine",
        "right": "he said it was fine",
        "type": "style","explanation_hindi": "व्यावसायिक भाषा में 'said' का प्रयोग 'told' से अधिक औपचारिक होता है।"
      }
    ]
  }

{
  "corrected": "Please take the necessary action and send the files.",
  "mistakes": [
    {
      "wrong": "Kindly do the needful",
      "right": "Please take the necessary action",
      "type": "style",
      "explanation_hindi": "यह वाक्यांश बहुत अस्पष्ट है और व्यावसायिक रूप से सही नहीं है।"
    }
  ]
}

{
    "corrected": "What is your name?",
    "mistakes": [
      {
        "wrong": "good name",
        "right": "name",
        "type": "style",
        "explanation_hindi": "व्यावसायिक बातचीत में 'good name' का उपयोग नहीं किया जाता है।"
      }
    ]
  }

{
  "corrected": "I have been working here for three years and I enjoy my role.",
  "mistakes": [
    {
      "wrong": "enjoy my role",
      "right": "find my role rewarding",
      "type": "style",
      "explanation_hindi": "आप 'enjoy' की जगह 'find rewarding' का उपयोग कर सकते हैं जो अधिक पेशेवर लगता है।"
    }
  ]
}

